using ll = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll a, b, f, k;
    cin >> a >> b >> f >> k;

    ll fuel = b;
    ll refuels = 0;

    for (ll trip = 0; trip < k; ++trip) {
        ll toStation = (trip % 2 == 0) ? f : a - f;

        if (fuel < toStation) {
            cout << -1 << '\n';
            return 0;
        }
        fuel -= toStation;

        ll required;
        if (trip == k - 1)
            required = (trip % 2 == 0) ? a - f : f;
        else
            required = (trip % 2 == 0) ? 2 * (a - f) : 2 * f;

        if (required > b) {
            cout << -1 << '\n';
            return 0;
        }

        if (fuel < required) {
            ++refuels;
            fuel = b;
        }

        fuel -= required;
    }

    cout << refuels << '\n';
    return 0;
}

